package com.autoops.embedding;import com.autoops.command.entity.CommandDefinition;import com.autoops.command.repository.CommandDefinitionRepository;import jakarta.persistence.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.stream.*;@Service public class EmbeddingService{private final EmbeddingProvider provider;private final CommandDefinitionRepository commands;@PersistenceContext private EntityManager em;public EmbeddingService(EmbeddingProvider p,CommandDefinitionRepository c){provider=p;commands=c;}public String vector(String text){float[]v=provider.embed(text);return IntStream.range(0,v.length).mapToObj(i->Float.toString(v[i])).collect(Collectors.joining(",","[","]"));}@Transactional public void index(CommandDefinition c){String text=String.join(" ",safe(c.getName()),safe(c.getDescription()),safe(c.getCategory()),safe(c.getAction()),safe(c.getResourceType()),safe(c.getCommandTemplate()));c.setEmbeddingText(text);c.setEmbeddingProvider(provider.provider());c.setEmbeddingModel(provider.model());commands.save(c);em.createNativeQuery("UPDATE command_definitions SET embedding=CAST(:v AS vector) WHERE id=:id").setParameter("v",vector(text)).setParameter("id",c.getId()).executeUpdate();}private String safe(String x){return x==null?"":x;}}
